style.css:
@-moz-document domain("roblox.com") {
/* ⚡ Dark JoJo Roblox Theme */
body {
    background: linear-gradient(135deg, #0a0a0f, #1a0033, #2b004f) !important;
    color: #e0d3ff !important;
    font-family: "Trebuchet MS", sans-serif !important;
}

/* ✨ Glow effect for UI blocks */
div, section, main {
    border-radius: 10px !important;
}

/* ? Game thumbnails glow */
img, video {
    border-radius: 12px !important;
    box-shadow: 0 0 20px #a855f7, 0 0 40px #7c3aed !important;
    transition: transform 0.2s ease, box-shadow 0.3s ease !important;
    animation: glowPulse 3s infinite alternate;
}

img:hover {
    transform: scale(1.05) !important;
    box-shadow: 0 0 30px #c084fc, 0 0 60px #7c3aed !important;
}

/* ? Remove clutter / ads */
nav, footer, aside,
[class*="ad"], [class*="banner"], [class*="promo"] {
    display: none !important;
}

/* ? Text styling */
h1, h2, h3, p, span, a {
    color: #c084fc !important;
    text-shadow: 0 0 8px #9333ea !important;
}

/* ⚡ JoJo menacing text */
body::before {
    content: "ゴ ゴ ゴ ゴ ゴ";
    position: fixed;
    top: 10%;
    left: 5%;
    font-size: 90px;
    color: rgba(168, 85, 247, 0.12);
    font-weight: bold;
    pointer-events: none;
    z-index: 9999;
}

/* ? Glow animation */
@keyframes glowPulse {
    from { box-shadow: 0 0 10px #7c3aed; }
    to   { box-shadow: 0 0 35px #c084fc; }
}
}
